# Create output grid initialized with background (8)
output = [[8 for _ in range(W)] for _ in range(H)]

# Apply transformation to each rectangle
for rect in rects:
    r_min, r_max = min(r for r,c in rect['cells']), max(r for r,c in rect['cells'])
    c_min, c_max = min(c for r,c in rect['cells']), max(c for r,c in rect['cells'])

    # For each cell in the rectangle, calculate minimum distance to any edge
    for r in range(r_min, r_max + 1):
        for c in range(c_min, c_max + 1):
            dist_to_edge = min(
                r - r_min,         # distance to top edge
                r_max - r,         # distance to bottom edge
                c - c_min,         # distance to left edge
                c_max - c          # distance to right edge
            )

            if dist_to_edge == 0:
                output[r][c] = 1  # outer border
            elif dist_to_edge == 1:
                output[r][c] = 4  # middle layer
            else:
                output[r][c] = 2  # inner core

# Print the result
print("Transformed grid:")
for row in output:
    print(' '.join(str(x) for x in row))

