        elif r == 0 and c in [1,2]:
            row_vals.append(4)  # top edge
        elif r == 2 and c in [1,2]:
            row_vals.append(4)  # bottom edge  
        elif c == 0 and r in [1]:
            row_vals.append(4)  # left edge
        elif c == 3 and r in [1]:
            row_vals.append(4)  # right edge
        else:
            row_vals.append(2)  # center
    print(f"Row {r}: {' '.join(map(str, row_vals))}")

